use super::*;

/// Top-level items declared PRIVATE to the module. The caller (`cohesion_reason`) keeps only the ones
/// that are NOT themselves extractable leaves — a private type or an impure/stateful private helper —
/// because a leaf that reaches that kind of item is entangled with parent complexity that stays behind.
/// A private item that is itself a pure leaf extracts alongside the others, so referencing it is an
/// inter-leaf call, not coupling.
///
/// PRIVACY IS SPELLED DIFFERENTLY BY EACH GRAMMAR, and that is the only real difference here. Rust
/// declares it by OMISSION — an item with no `visibility_modifier` child. TypeScript declares it by the
/// absence of an enclosing `export_statement`, which is a PARENT rather than a child, so the test is
/// made once at the top of the walk and the per-kind arms below never have to repeat it.
///
/// The kind arms are a union rather than a grammar branch: the two grammars' spellings do not collide,
/// so an arm the current language never emits simply never matches.
pub(crate) fn private_item_names(root: Node, src: &[u8]) -> std::collections::HashSet<String> {
    let mut names = std::collections::HashSet::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        // TypeScript: `export` is the visibility modifier and it WRAPS the declaration. An exported
        // item is public, so the whole statement is skipped before any kind is considered.
        if child.kind() == "export_statement" {
            continue;
        }
        match child.kind() {
            // ---- Rust: private is the ABSENCE of a `visibility_modifier` child.
            "function_item" | "struct_item" | "enum_item" | "const_item" | "static_item" | "type_item" | "union_item" => {
                let mut cc = child.walk();
                if child.children(&mut cc).any(|n| n.kind() == "visibility_modifier") {
                    continue;
                }
                if let Some(nm) = child.child_by_field_name("name") {
                    names.insert(nm.utf8_text(src).unwrap_or_default().to_string());
                }
            }
            // ---- TypeScript: reaching here at all means the item is not exported.
            "function_declaration" | "generator_function_declaration" | "class_declaration" | "interface_declaration"
            | "type_alias_declaration" | "enum_declaration" => {
                if let Some(nm) = child.child_by_field_name("name") {
                    names.insert(nm.utf8_text(src).unwrap_or_default().to_string());
                }
            }
            // A `const`/`let`/`var` statement binds one or more declarators, each its own name. A
            // destructuring pattern binds no single name this can record, so it is skipped rather than
            // recorded as an item literally called `{ a, b }`.
            "lexical_declaration" | "variable_declaration" => {
                let mut dc = child.walk();
                for d in child.named_children(&mut dc) {
                    if d.kind() != "variable_declarator" {
                        continue;
                    }
                    if let Some(nm) = d.child_by_field_name("name") {
                        if nm.kind() == "identifier" {
                            names.insert(nm.utf8_text(src).unwrap_or_default().to_string());
                        }
                    }
                }
            }
            _ => {}
        }
    }
    names
}
